update dir_states set license_status = 'license_required', license_threshold_cents = null, license_summary = 'Alaska requires every contractor, including specialty installers, to hold a state contractor registration (with bond and insurance) before bidding or working. Lavatory partitions fall under the sheet metal specialty category.', license_authority = 'Alaska Division of Corporations, Business and Professional Licensing (Construction Contractors)', license_source_url = 'https://Www.Commerce.Alaska.Gov/web/portals/5/pub/ContractorStatutes.pdf', license_checked = '2026-11-03' where code = 'AK';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'AS 08.18.011 requires registration to bid or work, no dollar threshold seen. 12 AAC 21.480 sheet metal specialty lists ''lavatory partitions''. Specialty bond $10,000 (AS 08.18.101/.171 area). Exemption 08.18.161(5) covers products that do not become a permanent fixed part of a structure; fixed partitions likely not covered. Plus Alaska business license and workers comp. Registration functions as the state license.' from dir_states where code = 'AK' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 10000000, license_summary = 'Commercial jobs of $100,000 or more need a state license from the Alabama Licensing Board for General Contractors. Smaller partition installs generally don''t need a state license, but cities and counties may require their own business registration.', license_authority = 'Alabama Licensing Board for General Contractors', license_source_url = 'https://genconbd.alabama.gov/14104/changes-to-the-alabama-licensing-board-for-general-contractors-section-of-the-code-of-alabama/', license_checked = '2026-11-03' where code = 'AL';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'Board page confirms threshold raised $50k to $100k effective 2024-10-01 (Act 2024-277). Many third-party guides still say $50k. Act 2026-396 (eff. 2026-10-01) amended 34-8-7 with new exemptions (routine maintenance, pools); thresholds not visible, full act PDF not read. Subcontractor treatment (sub of a licensed GC) not verified. No specialty class for partitions found. Confirm with board. Law: Citation from knowledge; official legislature page not opened.' from dir_states where code = 'AL' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 5000000, license_summary = 'Commercial jobs of $50,000 or more (labor and materials) need a license from the Arkansas Contractors Licensing Board; the board has a specialty class that includes partitions. Smaller jobs don''t need a state license, and splitting a job to stay under is barred.', license_authority = 'Arkansas Contractors Licensing Board', license_source_url = 'https://www.labor.arkansas.gov/wp-content/uploads/Commercial-Contractors-Law-revised-04.2026.pdf', license_checked = '2026-11-03' where code = 'AR';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'ACA 17-25-103: commercial contractor = non-residential work $50,000 or more; anti-splitting clause. Rule 17 CAR 255-308 specialty list includes ''Furniture, recreational and/or playground equipment, bleachers, seating, and partitions'' (specialty minimum net worth $5,000). Building permit offices must see license at $50k+.' from dir_states where code = 'AR' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 100000, license_summary = 'Arizona requires a state Registrar of Contractors license for commercial installation work of $1,000 or more. Smaller casual jobs without a permit are exempt, but a commercial partition installer should plan on being licensed.', license_authority = 'Arizona Registrar of Contractors', license_source_url = 'https://www.azleg.gov/ars/32/01121.htm', license_checked = '2026-11-03' where code = 'AZ';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'ARS 32-1121(A)(14): exempt only if aggregate price under $1,000, casual/minor, no permit, no advertising as contractor. Exact classification for toilet partitions NOT confirmed: R4-9-102 text (Cornell copy) shows C-10 Drywall (movable partitions, nonbearing steel partitions), C-24 Ornamental Metals, C-27 (closed to new applicants); no ''toilet partition'' wording. Ask ROC which C/CR class applies (a CR-10 style dual or B-general may be used).' from dir_states where code = 'AZ' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 100000, license_summary = 'California requires a CSLB license, usually the C-61/D-34 Prefabricated Equipment classification, for partition installs of $1,000 or more. Jobs needing workers or permits require a license at any price.', license_authority = 'California Contractors State License Board (CSLB)', license_source_url = 'https://www.cslb.ca.gov/About_Us/Library/Licensing_Classifications/Licensing_Classifications_Detail.aspx?Class=D34', license_checked = '2026-11-03' where code = 'CA';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'D-34 page text: ''all forms and types of toilet/shower room partitions/accessories''. Threshold: CSLB press release #24-21 (cslb.ca.gov/Resources/PressReleases/2024/AB2622.FINAL.pdf) and #24-07: AB 2622 (Ch. 240, Stats 2024) raised minor-work exemption $500 to $1,000 effective 2025-01-01, only if no workers hired and no permit. B (General Building) can also do it. Public school work (DSA) usually requires license regardless.' from dir_states where code = 'CA' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Colorado doesn''t license general or specialty contractors at the state level; only trades like electrical and plumbing are state licensed. Cities and counties set their own contractor licensing and registration rules.', license_authority = 'Colorado Department of Regulatory Agencies (DORA); local city and county building departments', license_source_url = 'https://dora.colorado.gov/consumer-protection-home-and-repair', license_checked = '2026-11-03' where code = 'CO';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'DORA consumer page (seen via search result snippet; direct fetch blocked 403) says not all occupations are licensed, e.g. roofers and general contractors. Local licensing varies (Denver etc.); not researched per-city. Electrical/plumbing state licenses not relevant to partitions.' from dir_states where code = 'CO' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Connecticut doesn''t require a state contractor license to install toilet partitions in typical commercial buildings. A Major Contractor registration applies only to large structural work on very large buildings. Check local requirements.', license_authority = 'Connecticut Department of Consumer Protection', license_source_url = 'https://portal.ct.gov/DCP/License-Services-Division/All-License-Applications/Major-Contractor-Registration-Application', license_checked = '2026-11-03' where code = 'CT';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'Major Contractor Registration (CGS ch. 541) applies to threshold buildings (4 stories, 60 ft, 150 ft span, 150,000 sq ft, 1,000 occupancy) and structural integrity work; partitions are non-structural. Home Improvement Contractor registration applies to residential only. Trade licenses (electrical, plumbing etc.) separate. Confirm with DCP for large/institutional buildings. Law: Summary fine. Major contractor registration is in ch. 393c; confirm § 20-341gg is the operative section.' from dir_states where code = 'CT' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'unclear', license_threshold_cents = null, license_summary = 'DC licenses general contractors and construction managers through the Department of Licensing and Consumer Protection. Whether a partition installer working as a subcontractor needs that license isn''t clear, so confirm with DLCP.', license_authority = 'DC Department of Licensing and Consumer Protection (DLCP)', license_source_url = 'https://dlcp.dc.gov/node/1616016', license_checked = '2026-11-03' where code = 'DC';
insert into dir_state_notes (slug, confidence, note) select slug, 'low', 'DLCP page only confirms General Contractor/Construction Manager is a licensed category (with Basic Business License + insurance COI). Secondary sources say GC/CM license is tiered by contract size (Class A-E) and some say no commercial GC license exists; Law 25-244 may split commercial/residential licensing. Need DLCP answer on subcontract specialty installers. Could not open DCMR text. Law: Sources conflict on whether DC issues a GC/CM license; a 2024 bill creating a Board of Construction Managers and General Contractors may have changed rules. Law citation unconfirmed; check DLCP.' from dir_states where code = 'DC' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'registration_only', license_threshold_cents = null, license_summary = 'Delaware has no state contractor license, but contractors doing construction work, including commercial, must register with the Department of Labor''s Contractor Registration program and hold a state business license. Local rules may add requirements.', license_authority = 'Delaware Department of Labor, Office of Contractor Registration', license_source_url = 'https://delcode.delaware.gov/title19/c036/index.shtml', license_checked = '2026-11-03' where code = 'DE';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', '19 Del. C. ch. 36: ''construction services'' includes all building or work on a building, structure or improvement; no general exemption list in 3602/3603. Registration fee about $200/yr (per secondary sources, $300 with state contract). Out-of-state firms need nonresident registration and bond (secondary source). Material suppliers excluded from ''worker'' only. Also Delaware business license from Division of Revenue.' from dir_states where code = 'DE' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'unclear', license_threshold_cents = null, license_summary = 'Florida has no state license category specifically for toilet partitions, and local governments can''t require a license for work outside the state''s defined categories. Contractors whose work matches a licensed category do need one; confirm with the state board.', license_authority = 'Florida Construction Industry Licensing Board (DBPR)', license_source_url = 'https://www.flsenate.gov/Laws/Statutes/2023/489.113', license_checked = '2026-11-03' where code = 'FL';
insert into dir_state_notes (slug, confidence, note) select slug, 'low', 'Fla. Stat. 489.103(9) exempts work under $2,500 casual/minor. 489.105(3) defines categories; partitions not named; specialty categories set by board rule (61G4-15), none for partitions found. 489.113(6)/163.211 (HB 735 2021, HB 1383 ch. 2023-271) bar local licensing outside matching scopes. Risk: a county may view interior build-out as general/building contractor scope. Not verified with DBPR. Statute pages opened: 489.103, 489.105, 489.113. Law: Citation is ch. 489 part I only; scope-of-license sections not individually verified.' from dir_states where code = 'FL' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'unclear', license_threshold_cents = 250000, license_summary = 'Georgia requires a state license for general contracting work over $2,500, but limited specialty trade work may be exempt. Whether a partition installer needs a license depends on how the job is contracted, so confirm with the state board.', license_authority = 'Georgia State Licensing Board for Residential and General Contractors', license_source_url = 'https://sos.ga.gov/49-reference-licensure-comparison-chart', license_checked = '2026-11-03' where code = 'GA';
insert into dir_state_notes (slug, confidence, note) select slug, 'low', 'Official pages returned 403, so only search snippets seen. O.C.G.A. 43-41-2: $2,500 (work value or compensation, whichever higher). A secondary source says 43-41-17(f) exempts specialty/limited/specific-trade contractors, but unverified; text could mean work for a licensed GC only. Commercial general contractor license for building construction; electrical/plumbing/conditioned air separate under ch. 14. Need confirmation from board. One site claims $100k commercial threshold - unsupported. Law: Section not individually verified; chapter only.' from dir_states where code = 'GA' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 150000, license_summary = 'Hawaii requires a state contractor license for most work above about $1,500, and the C-25 Institutional and Commercial Equipment specialty covers stationary metal partitions. Confirm the current limit with the Contractors License Board.', license_authority = 'Hawaii Contractors License Board (DCCA)', license_source_url = 'https://cca.hawaii.gov/wp-content/uploads/2026/01/DescriptionofContractorLicenseClassifications-1.pdf', license_checked = '2026-11-03' where code = 'HI';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'Classification PDF: C-25 includes ''folding and sliding partitions... stationary metal partitions'' and lockers; C-5 covers nonbearing partitions; C-44 sheet metal covers nonbearing metal partitions. Threshold: HRS 444-2 handyman exemption raised from $1,000 to $1,500 by Act 283 (2019) per text of 2026 bill HB846 (not enacted as far as seen; proposed $2,500). HRS page itself returned 403 - verify. Applies to labor, materials plus other conditions; commercial work generally licensed. Law: Citation from knowledge; official legislature page not opened.' from dir_states where code = 'HI' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
