insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Verified on DIAL page and Iowa Code 91C.1. Program moved from Iowa Workforce Development to DIAL. $50 fee, annual renewal; out-of-state contractors generally need a $25,000 bond; employers need workers comp certificate. Plumbing/mechanical need separate license.' from dir_states where code = 'IA' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
