insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Official page: ''If a project is valued at $40,000 or more, your general contractor must have a license issued by the state.'' Threshold raised from $30,000 on 2023-10-01 (G.S. 87-1) per secondary sources. Threshold is on the whole project cost, not just partition scope; board watches for split contracts. Local permit may still require proof of license or exemption.' from dir_states where code = 'NC' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 400000, license_summary = 'North Dakota requires a state contractor license for jobs over $4,000, with the license class set by contract size. A typical partition job above that amount needs a Secretary of State contractor license.', license_authority = 'North Dakota Secretary of State, Contractor Licensing', license_source_url = 'https://sos.nd.gov/business/contractors', license_checked = '2026-11-03' where code = 'ND';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Official page: license required when job cost/value/price exceeds $4,000 (NDCC ch. 43-07); classes A (>$500k), B (up to $500k), C (up to $300k), D (up to $100k). Page lists no exemptions; call SOS (701-328-2900) for specialty-trade exemption questions. Fees are as the page lists them.' from dir_states where code = 'ND' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'registration_only', license_threshold_cents = null, license_summary = 'Nebraska has no state contractor license. Installers doing work on other people''s property must register with the Department of Labor, with workers'' compensation proof if they have employees. Some cities and counties, such as Lincoln and Douglas County, add their own licenses.', license_authority = 'Nebraska Department of Labor, Contractor Registration (Labor Standards)', license_source_url = 'https://dol.nebraska.gov/LaborStandards/Contractors', license_checked = '2026-11-03' where code = 'NE';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Official page: all contractors doing business in NE must register; annual fee rises to $40 on 2026-08-01 (was $25). No dollar threshold or exemptions listed on the page. Local licensing (Lincoln commercial business license, Douglas County exam/bond) came from secondary sources, not verified.' from dir_states where code = 'NE' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'New Hampshire has no state license for general or specialty construction contractors; the state licenses trades like electricians. Cities and towns may require local permits or registration, so check with the local building department.', license_authority = 'New Hampshire Office of Professional Licensure and Certification (OPLC)', license_source_url = 'https://www.oplc.nh.gov/find-board/electricians-board', license_checked = '2026-11-03' where code = 'NH';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'No official page found that states ''no GC license'' outright; conclusion rests on several third-party licensing guides plus OPLC electricians'' board existing. That URL was only seen in search results, not opened. Confirm by phone with OPLC (603-271-2152). Partitions are not an electrical/plumbing trade.' from dir_states where code = 'NH' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'New Jersey has no state license for commercial installers. State home improvement contractor registration applies only to residential work. Commercial jobs fall under local rules, so check with the municipality where the restroom is located.', license_authority = 'New Jersey Division of Consumer Affairs, Home Improvement Contractor Registration', license_source_url = 'https://njconsumeraffairs.gov/hic/Pages/FAQ.aspx', license_checked = '2026-11-03' where code = 'NJ';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'Fetch of the FAQ page returned empty; conclusion (HIC Act under N.J.S.A. 56:8-136 ff. does not apply to commercial property) comes from search-result snippets of the Division''s FAQ and municipal FAQs. Re-read FAQ for exact wording. Installers who also do residential work must register ($110 initial fee per NJBIA; bond/security added 2024). Some municipalities require local contractor registration.' from dir_states where code = 'NJ' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'license_required', license_threshold_cents = null, license_summary = 'New Mexico requires a state contractor license for construction work. Partition installation is not named in the classification list, so installers typically hold a general building license (GB-98) or the miscellaneous specialty license (GS-29). Confirm which applies with the Construction Industries Division.', license_authority = 'New Mexico Regulation and Licensing Department, Construction Industries Division (CID)', license_source_url = 'https://www.srca.nm.gov/parts/title14/14.006.0006.html', license_checked = '2026-11-03' where code = 'NM';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', '14.6.6 NMAC read: toilet partitions not named; GS-29 is the catch-all for CID-regulated work not listed; GB-98 includes all GS scopes. GS-7 (drywall/non-structural stud) is nearest named scope. Statute (NMSA 60-13-1 ff.) bars acting as a contractor without a license; exemptions with dollar limits exist but were not read (some secondary sources say $7,200/year). Ask CID which class they assign for partition installs.' from dir_states where code = 'NM' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'license_required', license_threshold_cents = 100000, license_summary = 'Nevada requires a state contractor''s license, and toilet partitions fall under the C-8 Glass and Glazing classification. Only small repair jobs under $1,000 that need no permit are exempt. Confirm the classification with the Nevada State Contractors Board.', license_authority = 'Nevada State Contractors Board', license_source_url = 'https://www.leg.state.nv.us/nac/NAC-624.html', license_checked = '2026-11-03' where code = 'NV';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'NAC 624.260 text read on the legislature site: C-8 may install, repair and replace enclosures for showers and tubs and toilet partitions; former C-8d holders deemed C-8 restricted to those enclosures/partitions. The $1,000 repair/maintenance exemption (NRS 624.220(6)) came from a search summary, not read in the statute; a $3,000+ partition job is above it anyway. Other classifications (e.g. general building B) may also cover it; confirm with NSCB. Law: NAC 624.260 taken from the example in the task; classification (C-8) not independently verified here.' from dir_states where code = 'NV' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'New York State does not license commercial installers like this. New York City requires general contractor registration with the Department of Buildings for certain work, and some counties license home improvement contractors. Check local rules for the building''s location.', license_authority = 'NYC Department of Buildings (city); no statewide licensing agency', license_source_url = 'https://www.nyc.gov/site/buildings/industry/general-contractor-registration.page', license_checked = '2026-11-03' where code = 'NY';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'NYC page read says GC registration is tied to building 1-, 2-, 3-family homes (new building permits); it does not say whether interior commercial work needs it. Absence of a NYS general contractor license inferred from DOS licensing-services listing and secondary sources, not stated by an official page. HIC licensing is residential and local (NYC, Nassau, Suffolk, Westchester, Putnam, Rockland). Confirm NYC DOB for NYC jobs.' from dir_states where code = 'NY' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Ohio licenses only five commercial trades at state level: electrical, HVAC, hydronics, plumbing and refrigeration. Partition installation isn''t one of them, but many cities and counties have their own contractor registration, so check locally.', license_authority = 'Ohio Construction Industry Licensing Board (Ohio Department of Commerce)', license_source_url = 'https://com.ohio.gov/divisions-and-programs/industrial-compliance/boards/ohio-construction-industry-licensing-board', license_checked = '2026-11-03' where code = 'OH';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'The OCILB page was only seen in search results (my fetch of it returned 404), so the five-trade scope comes from the search summary of that page plus ORC ch. 4740. Local city/county contractor registration varies widely.' from dir_states where code = 'OH' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Oklahoma has no state license for general construction or most specialty installers. The state licenses plumbing, electrical, mechanical and roofing work only. Cities and counties may have their own registration, so check locally.', license_authority = 'Oklahoma Construction Industries Board', license_source_url = 'https://oklahoma.gov/cib/frequently-asked-questions.html', license_checked = '2026-11-03' where code = 'OK';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'CIB FAQ read: ''General Contractors are not currently required to have a state license in Oklahoma''; regulated trades are plumbing, electrical, mechanical, roofing, inspectors. Out-of-state contractors may need Oklahoma Tax Commission nonresident registration (secondary source, unverified). Local rules (OKC, Tulsa) apply.' from dir_states where code = 'OK' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'license_required', license_threshold_cents = null, license_summary = 'Oregon requires a Construction Contractors Board license with a commercial endorsement for commercial construction work, including specialty trades. Installers should hold a commercial specialty or general endorsement; confirm which level fits the job with the CCB.', license_authority = 'Oregon Construction Contractors Board (CCB)', license_source_url = 'https://www.oregon.gov/ccb/pages/ccb%20license.aspx', license_checked = '2026-11-03' where code = 'OR';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'CCB page read: license generally required for construction work on real property; commercial endorsements CGC1, CGC2, CSC1, CSC2 (commercial developer excluded) with bonds/insurance. No dollar threshold or exemption for partitions found. CSC1 vs CSC2 rules (project size limits) not confirmed on an official page (ORS 701.021 / OAR 812 not read). Ask CCB which level applies.' from dir_states where code = 'OR' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Pennsylvania has no state license for commercial installers. State home improvement registration covers residential work only. Commercial jobs fall under local rules, such as Philadelphia''s contractor license, so check with the municipality.', license_authority = 'Pennsylvania Office of Attorney General, Home Improvement Contractor Registration', license_source_url = 'https://hic.attorneygeneral.gov', license_checked = '2026-11-03' where code = 'PA';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'HIC site returned 503 and AG instruction PDF 404, so not actually read; conclusion from search snippets (HICPA 73 P.S. 517.1 ff.: $5,000/yr residential threshold, commercial exempt) and Philadelphia code interpretation requiring local licenses for non-residential work. Confirm HICPA text. Retail-property subcontractor carve-out noted in AG instructions.' from dir_states where code = 'PA' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'registration_only', license_threshold_cents = null, license_summary = 'Rhode Island requires contractors who build or repair commercial or residential structures to register with the state Contractors'' Registration and Licensing Board. Commercial-only contractors are exempt from the pre-registration and continuing education courses.', license_authority = 'Rhode Island Contractors'' Registration and Licensing Board (CRLB)', license_source_url = 'https://rules.sos.ri.gov/Regulations/part/440-10-00-2', license_checked = '2026-11-03' where code = 'RI';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'Rule text (Section 2.2) says every contractor, remodeler and most subcontractors must register; sub exclusions not stated on page. Minor work under $500 definition (2.4B) unclear re exemption. crb.ri.gov pages returned 403; search snippets of CRB FAQ say commercial contractors must be registered. Confirm whether a partition-only installer counts as a subcontractor needing registration.' from dir_states where code = 'RI' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 1000000, license_summary = 'South Carolina requires a state contractor license when a commercial project''s total construction cost is over $10,000. Smaller jobs fall below the state threshold; local business licenses may still apply.', license_authority = 'South Carolina Contractors'' Licensing Board (LLR)', license_source_url = 'https://www.llr.sc.gov/clb/PDFFiles/CLB2023LegislativeUpdate.pdf', license_checked = '2026-11-03' where code = 'SC';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', '2023 LLR update: threshold raised from $5,000 to >$10,000 for general and mechanical contracting (Act 69/H4115). Threshold is on total cost of construction, so a partition sub on a larger project may be pulled in. Specialty subclass ''Nonstructural Renovation'' (formerly Interior Renovation) likely fits; not confirmed that partitions-only work needs it. Confirm with Board.' from dir_states where code = 'SC' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'South Dakota has no state contractor license for this work. Contractors do need a state contractor''s tax license from the Department of Revenue. Check city or county rules where the job is.', license_authority = 'South Dakota Department of Revenue (contractor''s excise tax); local city/county', license_source_url = 'https://dor.sd.gov/businesses/taxes/contractors-excise-tax/', license_checked = '2026-11-03' where code = 'SD';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'DOR page confirms tax license is required for construction/installation work (tax, not competency, license). ''No state GC license'' rests on secondary sources only; no official page opened stating it. Electrical/plumbing are state-licensed separately. Some cities license contractors.' from dir_states where code = 'SD' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 2500000, license_summary = 'Tennessee requires a state contractor license to bid or take commercial projects of $25,000 or more. Subcontractors in trades like drywall or carpentry are not required to hold one when working for a contractor.', license_authority = 'Tennessee Board for Licensing Contractors', license_source_url = 'https://www.tn.gov/content/dam/tn/commerce/documents/regboards/contractors/forms/ContLicenseApplicationWeb.pdf', license_checked = '2026-11-03' where code = 'TN';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Board application package: license required for prime contracting >= $25,000; subs only for electrical, mechanical, plumbing, HVAC, roofing >= $25,000 and masonry >= $100,000; ''drywall, painting, landscaping, carpentry, etc.'' subs exempt when working for a contractor. A partitions installer bidding directly to the owner/facility at $25k+ is a prime and needs a license (BC-B/commercial or a classification covering 60%). Under $25k: no state contractor license (home improvement license is residential). Law: Citation from knowledge; official legislature page not opened.' from dir_states where code = 'TN' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Texas does not license general or specialty contractors for this work at the state level. Cities may require contractor registration to pull permits, for example Dallas.', license_authority = 'Texas Governor''s Office guide to state licenses; local city building departments', license_source_url = 'https://gov.texas.gov/uploads/files/business/Texas_Licenses_Permits_Guide.pdf', license_checked = '2026-11-03' where code = 'TX';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Official guide: ''General contractors are not required to obtain a license to practice in Texas.'' Trade licenses (TDLR: electrical, ACR) do not cover partitions. Dallas Chapter 52 registration from prior notes not re-verified.' from dir_states where code = 'TX' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 700000, license_summary = 'Utah requires a contractor license for alteration or remodel work valued at $7,000 or more, including labor and materials. Between $3,000 and $7,000, a one-time insurance affirmation is filed with the state.', license_authority = 'Utah Division of Professional Licensing (DOPL)', license_source_url = 'https://le.utah.gov/xcode/Title58/Chapter55/C58-55-S305_2025050720250507.html', license_checked = '2026-11-03' where code = 'UT';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'Utah Code 58-55-305(1)(h) (version effective 5/7/2025; renumbering 1/1/2027): exempt if contracted value < $7,000 (affirmation required if > $3,000). Earlier $3,000 figure from secondary sources is outdated. Specialty classes are in R156-55a; no verified class for toilet partitions; (1)(i) exempts specialty classes not deemed significant to public health/safety. Ask DOPL which class, if any, covers partitions.' from dir_states where code = 'UT' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 100000, license_summary = 'Virginia requires a state contractor license for commercial jobs over $1,000. Class C covers single jobs up to $30,000, Class B up to $150,000, and Class A $150,000 and above.', license_authority = 'Virginia Board for Contractors (DPOR)', license_source_url = 'https://law.lis.virginia.gov/vacode/title54.1/chapter11/section54.1-1100/', license_checked = '2026-11-03' where code = 'VA';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Va. Code 54.1-1100: Class C > $1,000 and < $30,000 per job (or < $250,000 per 12 months); Class B $30k-<$150k; Class A >= $150k. Class B/A also need net worth. Specialty designation for partitions not verified (DPOR has specialties e.g. CBC, drywall, ACM); confirm which designation. Exemptions in 54.1-1101 not read.' from dir_states where code = 'VA' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Vermont has no state contractor license for commercial partition installation. State registration applies to residential contractors on jobs of $10,000 or more. Only electrical and plumbing work is state-licensed. Check town rules.', license_authority = 'Vermont Office of Professional Regulation (Secretary of State)', license_source_url = 'https://sos.vermont.gov/residential-contractors/residential-contractor-faqs', license_checked = '2026-11-03' where code = 'VT';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'OPR FAQ: registration is for residential jobs >= $10,000 (since April 2023); not for commercial-only work. ''No general contractor license'' for commercial relies on that plus secondary sources; no official statement opened saying so outright. Law: Verified residential registration only; confirm no commercial requirement.' from dir_states where code = 'VT' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'registration_only', license_threshold_cents = null, license_summary = 'Washington requires every construction contractor to register with Labor & Industries. Specialty contractors can only do work in their registered specialty and generally cannot hire subcontractors.', license_authority = 'Washington State Department of Labor & Industries (L&I)', license_source_url = 'https://lni.wa.gov/licensing-permits/contractors/register-as-a-contractor/', license_checked = '2026-11-03' where code = 'WA';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Verified on L&I page: all construction contractors register; specialty only within specialty; $15,000 specialty bond vs $30,000 general. Registration (not exam-based licensing). Confirm which of the 63 specialties, if any, covers toilet partitions, or register as general.' from dir_states where code = 'WA' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Wisconsin does not license contractors for commercial work at the state level. State licensing covers one- and two-family dwelling contractors and certain trades, such as electrical and HVAC. Commercial jobs go through state plan review and local permits.', license_authority = 'Wisconsin Department of Safety and Professional Services (DSPS)', license_source_url = 'https://dsps.wi.gov/Pages/Professions/DwellingContractorQualifier/Default.aspx', license_checked = '2026-11-03' where code = 'WI';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'DSPS page opened covers only the dwelling contractor credential (1-2 family homes). Absence of commercial general contractor license rests on secondary sources and DSPS commercial-building pages (plan review). Confirm with DSPS (608-266-2112). Law: Citation from memory; official page unreachable.' from dir_states where code = 'WI' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'above_threshold', license_threshold_cents = 2500000, license_summary = 'West Virginia requires a state contractor license for commercial work costing $25,000 or more (residential $5,000). Smaller commercial jobs fall below the state requirement.', license_authority = 'West Virginia Contractor Licensing Board (Division of Labor)', license_source_url = 'https://code.wvlegislature.gov/30-42-3/', license_checked = '2026-11-03' where code = 'WV';
insert into dir_state_notes (slug, confidence, note) select slug, 'medium', 'W.Va. Code 30-42-3(d) defines contractor at $5,000 residential / $25,000 commercial; third-party $2,500 figure is outdated. Page lacks the operative mandate section (30-42-5?). Classes include general building and specialty; painting and landscaping excluded; whether partitions-only needs a specialty class is not confirmed. Board FAQ says threshold counts whole project cost, so subs on large jobs may need license.' from dir_states where code = 'WV' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
update dir_states set license_status = 'no_state_license', license_threshold_cents = null, license_summary = 'Wyoming does not license contractors at the state level, except electrical. Licensing is left to the city or county where the work happens, so check local rules.', license_authority = 'Wyoming Business Council; local city/county licensing offices', license_source_url = 'http://www.wyomingbusiness.org/business/start/startup-resources/', license_checked = '2026-11-03' where code = 'WY';
insert into dir_state_notes (slug, confidence, note) select slug, 'high', 'Business Council page: ''Contractor licensing (except electrical) is not done by the state of Wyoming...deferred to the local jurisdiction.'' Local rules vary (e.g., Cheyenne, Casper not checked).' from dir_states where code = 'WY' on conflict (slug) do update set confidence = excluded.confidence, note = excluded.note;
